import { useEffect, useState } from 'react';
/**
 * The MfeWrapper allows an MFE to be rendered in a way where
 * the props can be updated externally using the dynamic config controller's updateConfig() function.
 */
export function MfeWrapper(props) {
    const [configObject, setConfigObject] = useState(props.configController.getDefaultConfig());
    useEffect(() => {
        props.configController.setUpdaterFunction(setConfigObject);
        return () => {
            props.configController.clearUpdaterFunction();
        };
    }, []);
    return props.mfeComponent(configObject);
}
